input.script:
export const meta = {
  name: 'ajcr-t5-signature-map',
  description: 'Map exact signatures for T5 rank-one divisor uniqueness assembly',
  phases: [{ title: 'Read', detail: 'six parallel readers over the T5 dependency cone' }],
}

const ROOT = '/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'

const SCHEMA = {
  type: 'object',
  properties: {
    declarations: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          signature: { type: 'string', description: 'full Lean signature, verbatim including implicit args, instance args' },
          notes: { type: 'string', description: 'what it does, hypotheses that matter (esp. Noetherian), definitional behavior' },
        },
        required: ['name', 'file', 'signature'],
      },
    },
    idioms: { type: 'array', items: { type: 'string' } },
    hazards: { type: 'array', items: { type: 'string' } },
  },
  required: ['declarations', 'idioms', 'hazards'],
}

const READERS = [
  {
    key: 'presentation',
    files: ['AlgebraicJacobian/Picard/Pic0RankOnePresentation.lean'],
    want: 'PicRankOneLocalPresentation: ALL fields verbatim (cover, datum, representative, datum_class, h0 fields, h0BaseChange at line ~107, datumSection, sectionLocalEquationsOfDatumSectionBaseChange ~318) — especially every field/lemma relating P.datum, P.representative, the class equation datum_class (line ~72), and what relates lam to the datum cechPicClass',
  },
  {
    key: 'locus',
    files: ['AlgebraicJacobian/Picard/Pic0RankOneLocus.lean'],
    want: 'PicRankOneOpen: exact definition of the subfunctor, membership predicate, picRankOneOpen_map_mem (~209), PicRankOneLocalPresentation existence lemmas (any exists_localPresentation or nonempty lemmas, esp. any at the identity test t = id showing membership gives a presentation of the class itself), picEtAffineEquiv occurrences, picDegLayer',
  },
  {
    key: 'divfam-abel',
    files: ['AlgebraicJacobian/Picard/DivisorFamilyAffAbel.lean', 'AlgebraicJacobian/Picard/DivisorFamilyAffZar.lean'],
    want: 'DivFamZarAff: definition, picClass field/def, abelDivAffPlus definition and abelDivAffPlus_mapAlgHom (~125), abelDivAff_val or abelDivAff2 (~184) componentwise lemmas, relPicMk and how abelDivAffPlus relates to relPicMk of picClass, mapAlgHom action on picClass, DivFamZarAff equality lemmas (ext lemmas)',
  },
  {
    key: 'away-span',
    files: ['AlgebraicJacobian/Picard/DivRepAwaySpanGlueAff.lean', 'AlgebraicJacobian/Picard/DivSchemeCertZarPointwise.lean'],
    want: 'DivFamZarAff.eq_of_awaySpan_eq (~99) exact statement, DivFamZarAff.exists_glue_of_awaySpan (~38), exists_fin_span_eq_top_of_forall_prime (~57) exact statement — the pointwise-to-global glue interfaces',
  },
  {
    key: 'mono-h1',
    files: ['AlgebraicJacobian/Picard/DivisorFamilyMonoH1.lean'],
    want: 'Module.exists_notMem_bijective_toSpanSingleton (~60), exists_notMem_smul_eq_of_tmul_ne_zero (~215), Module.bijective_toSpanSingleton_of_forall_tmul_ne_zero, Module.existsUnique_unit_smul_of_forall_tmul_ne_zero — exact statements with all hypotheses (finite, projective, rank-one), and any localization lemmas producing f not in q with freeness',
  },
  {
    key: 'etale-descent',
    files: ['AlgebraicJacobian/Picard/PicEtAffEtaleSeparated.lean', 'AlgebraicJacobian/Picard/Pic0AdmissibleAbelEtaleSurjectiveSite.lean', 'AlgebraicJacobian/Picard/DivRepAffFaithfullyFlatDescent.lean'],
    want: 'PicEtAff.map_injective_of_etaleCover, PicEtAff.unit_injective and PicEtAff.mapAlg_mk_eq_unit_self (~106 in SurjectiveSite), DivFamZarAff.exists_descent_of_tensor_eq (~138 in FaithfullyFlatDescent), and ANY mapAlgHom_injective_of_faithfullyFlat or DivFamZarAff injectivity-under-faithfully-flat lemma — exact statements',
  },
]

phase('Read')
const results = await parallel(READERS.map(r => () =>
  agent(
    `You are mapping Lean 4 source for a proof-engineering task in the repo ${ROOT} (project AlgebraicJacobian).\n\n` +
    `Read these files COMPLETELY:\n${r.files.map(f => ROOT + '/' + f).join('\n')}\n\n` +
    `Extract: ${r.want}\n\n` +
    `Report EVERY declaration relevant to the ask with its VERBATIM signature (copy the source text of the statement including binders, instance brackets, hypotheses) plus 1-3 sentences of notes. List proof idioms and hazards (Noetherian/finiteness hypotheses, defeq-sensitive definitions). Line numbers matter. If an asked-for name does not exist in these files, say so explicitly in hazards and name the closest actual declaration.`,
    { label: `read:${r.key}`, phase: 'Read', schema: SCHEMA, model: 'opus' }
  )
))
return Object.fromEntries(READERS.map((r, i) => [r.key, results[i]]))
